CREATE TABLE CPF_RUNTIME_LOCK (
    LOCK_KEY VARCHAR(200) NOT NULL,
    OWNER_ID VARCHAR(200) NOT NULL,
    REQUEST_ID VARCHAR(200) NOT NULL,
    FENCING_TOKEN BIGINT NOT NULL,
    OWNER_EPOCH BIGINT NOT NULL,
    VERSION_NO BIGINT NOT NULL,
    ACQUIRED_AT DATETIME(6) NOT NULL,
    LEASE_UNTIL DATETIME(6) NOT NULL,
    LOCK_STATE VARCHAR(32) NOT NULL,
    LAST_REASON VARCHAR(1000) NULL,
    UPDATED_AT DATETIME(6) NOT NULL,
    CONSTRAINT PK_CPF_RUNTIME_LOCK PRIMARY KEY (LOCK_KEY),
    CONSTRAINT CK_CPF_RUNTIME_LOCK_STATE CHECK (LOCK_STATE IN ('ACTIVE','RELEASED','EXPIRED','FORCE_RELEASED')),
    CONSTRAINT CK_CPF_RUNTIME_LOCK_TOKEN CHECK (FENCING_TOKEN >= 1 AND OWNER_EPOCH >= 1 AND VERSION_NO >= 1)
) ENGINE=InnoDB;
CREATE INDEX IDX_CPF_RUNTIME_LOCK_LEASE ON CPF_RUNTIME_LOCK (LOCK_STATE, LEASE_UNTIL, LOCK_KEY);
CREATE INDEX IDX_CPF_RUNTIME_LOCK_OWNER ON CPF_RUNTIME_LOCK (OWNER_ID, REQUEST_ID, LOCK_STATE);
